// Gera uma única identidade da execução antes de abrir os dois branches.
const entrada=$json||{};
const conta=entrada.conta||'742175035567342';
const planilhaId=entrada.planilha_id||'1S2r2y1AiaUnZPUpR0qTp_8Itag5n1DhH6rCrXaFAH1A';
const data=entrada.pacote_analise?.data_referencia||$now.setZone('America/Sao_Paulo').minus({days:1}).toFormat('yyyy-MM-dd');
const gerado=$now.setZone('America/Sao_Paulo').toISO();
const chaveAnalise=[conta,data,gerado].join('|');
return [{json:{...entrada,CONFIG_PLANILHA:{PLANILHA_ID:planilhaId,CONTA:conta,ABA_ANALISES:'ANALISES IA',ABA_PRIORIDADES:'PRIORIDADES IA',DATA_REFERENCIA:data,GERADO_EM:gerado,CHAVE_ANALISE:chaveAnalise}}}];

// Cria uma linha por execução válida da IA usando a chave compartilhada.
if($json.status_analise_ia!=='OK'||!$json.analise_ia)return[];
const a=$json.analise_ia||{},p=$json.pacote_analise||{},perf=p.performance||{},tend=p.tendencia||{},cfg=$json.CONFIG_PLANILHA||{};
const prioridades=Array.isArray(a.prioridades)?a.prioridades:[];const primeira=prioridades[0]||{};
return [{json:{PLANILHA_ID:cfg.PLANILHA_ID,'CHAVE ANALISE':cfg.CHAVE_ANALISE,'DATA REFERENCIA':cfg.DATA_REFERENCIA,'GERADO EM':cfg.GERADO_EM,'CONTA':cfg.CONTA,'SAUDE CONTA':String(a.saude_conta||'dados_insuficientes').toUpperCase(),'CONFIANCA ANALISE':String(a.confianca_analise||'baixa').toUpperCase(),'RESUMO EXECUTIVO':String(a.resumo_executivo||''),'INVESTIMENTO TOTAL':perf.investimento_total??'','CONVERSAS':perf.conversas_iniciadas??'','CUSTO MEDIO CONVERSA':perf.custo_medio_por_conversa??'','SCORE TECNICO MEDIO':perf.score_tecnico_medio??'','QTD OBJETOS':tend.quantidade_objetos??perf.quantidade_registros??'','FADIGA ALTA':Array.isArray(tend.fadiga_alta)?tend.fadiga_alta.length:0,'FADIGA MODERADA':Array.isArray(tend.fadiga_moderada)?tend.fadiga_moderada.length:0,'OBSERVAR':Array.isArray(tend.observar)?tend.observar.length:0,'MELHORA':Array.isArray(tend.melhora)?tend.melhora.length:0,'DADOS INSUFICIENTES':Array.isArray(tend.dados_insuficientes)?tend.dados_insuficientes.length:0,'QTD PRIORIDADES':prioridades.length,'PRIORIDADE PRINCIPAL':String(primeira.nome||''),'ACAO PRINCIPAL':String(primeira.acao_recomendada||''),'BRIEFING GESTOR':String($json.briefing_gestor||''),'PARSER':String($json.parser_usado||'')}}];

// Expande as prioridades usando exatamente a mesma CHAVE ANALISE do resumo.
if($json.status_analise_ia!=='OK'||!$json.analise_ia)return[];
const a=$json.analise_ia||{},cfg=$json.CONFIG_PLANILHA||{};const prioridades=Array.isArray(a.prioridades)?a.prioridades:[];
return prioridades.map((x,i)=>({json:{PLANILHA_ID:cfg.PLANILHA_ID,'CHAVE PRIORIDADE':[cfg.CHAVE_ANALISE,x.prioridade||i+1].join('|'),'CHAVE ANALISE':cfg.CHAVE_ANALISE,'DATA REFERENCIA':cfg.DATA_REFERENCIA,'CONTA':cfg.CONTA,'ORDEM':Number(x.prioridade||i+1),'NIVEL':String(x.nivel||''),'NOME OBJETO':String(x.nome||''),'ACAO RECOMENDADA':String(x.acao_recomendada||'OBSERVAR'),'DIAGNOSTICO':String(x.diagnostico||''),'MOTIVO':String(x.motivo||''),'EVIDENCIAS':Array.isArray(x.evidencias)?x.evidencias.join(' | '):'','REAVALIAR EM DIAS':Number(x.prazo_reavaliacao_dias||3),'STATUS GESTOR':'PENDENTE','OBSERVACAO GESTOR':'','ATUALIZADO EM':cfg.GERADO_EM}}));

